const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const powerIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M12 3v9M7 5.5a8 8 0 1 0 10 0" stroke-linecap="round"/></svg>';
const escapeHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let settings=clone(PRESETS[0].settings),activePreset=PRESETS[0],library='factory',saved=[],dirty=false,busy=false,noticeTimer,storageTimer,recordURL,recordStopping=false,loopStarted=0;
const selectedFolder={factory:null,saved:null};let presetQuery='',movingPresetId=null;
const folderIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M3 7V5a1 1 0 0 1 1-1h5l2 3h9a1 1 0 0 1 1 1v11a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V7Z"/></svg>';
try{saved=restoreSavedPresets(JSON.parse(localStorage.getItem('voltage.presets')||'[]'));}catch{}
try{const v=JSON.parse(localStorage.getItem('voltage.session')||'null');if(v){const factory=PRESETS.find(p=>p.id===v.presetId);dirty=Boolean(v.dirty);activePreset=factory||saved.find(p=>p.id===v.presetId)||PRESETS[0];settings=factory&&!dirty?clone(factory.settings):sanitizeSettings(v.settings);if(settings.cabinet==='custom')settings.cabinet='open';}}catch{}
const engine=new GuitarEngine({onState:renderStatus,onError:showError,onLooper:renderLooper,onBeat:beat=>{$('#metronome-status').textContent=`${beat+1} / 4 · Playing`;$('.metronome-tool').classList.add('beat-flash');setTimeout(()=>$('.metronome-tool').classList.remove('beat-flash'),80);}});
function notify(message){clearTimeout(noticeTimer);$('#notice').textContent=message;$('#notice').classList.add('visible');noticeTimer=setTimeout(()=>$('#notice').classList.remove('visible'),6500);}
function showError(message){notify(message);$('#connection-error').textContent=message;$('#connection-error').hidden=false;}
function clearError(){$('#connection-error').hidden=true;}
function saveSession(){clearTimeout(storageTimer);storageTimer=setTimeout(()=>{try{localStorage.setItem('voltage.session',JSON.stringify({settings,presetId:activePreset.id,dirty}));}catch{}},200);}
function changed(){dirty=true;engine.update(settings);renderTone();saveSession();}
const format=(v,u)=>`${Number.isInteger(v)?v:v.toFixed(1)}${['%','s'].includes(u)?u:' '+u}`;
function renderPresets(){
  $('#saved-count').textContent=saved.length;$$('[data-library]').forEach(b=>{b.classList.toggle('selected',b.dataset.library===library);b.setAttribute('aria-pressed',String(b.dataset.library===library));});
  const folders=getLibraryFolders(library,saved,presetQuery),folder=folders.find(f=>f.id===selectedFolder[library]);
  if(!folder)selectedFolder[library]=null;
  const visible=folders.filter(f=>f.presets.length),count=folder?folder.presets.length:visible.reduce((n,f)=>n+f.presets.length,0);
  $('#folder-heading').textContent=folder?folder.name:'Folders';$('#folder-back').hidden=!folder;
  $('#folder-count').textContent=`${count} ${presetQuery?'matching ':''}tone${count===1?'':'s'}${folder?'':` · ${visible.length} folders`}`;
  $('#preset-list').classList.toggle('folder-view',!folder);
  if(!folder){
    $('#preset-list').innerHTML=visible.length?visible.map(f=>`<button class="folder-button" data-folder="${escapeHTML(f.id)}" style="--folder-color:${f.color}" aria-label="Open ${escapeHTML(f.name)}, ${f.presets.length} tones"><span class="folder-icon">${folderIcon}</span><span class="folder-copy"><strong>${escapeHTML(f.name)}</strong><small>${escapeHTML(f.description)}</small></span><span class="folder-size">${f.presets.length}</span></button>`).join(''):library==='saved'&&!saved.length?'<p class="empty-presets">Dial in a sound, then save it to your first folder. Older saved tones appear in My tones.</p>':'<p class="empty-presets">No tones match. Try a different name or effect.</p>';
    return;
  }
  $('#preset-list').innerHTML=folder.presets.length?folder.presets.map(p=>`<div class="${library==='saved'?'saved-row':'factory-row'}"><button class="preset-button ${activePreset.id===p.id?'active':''}" data-preset="${escapeHTML(p.id)}" aria-pressed="${activePreset.id===p.id}" title="${escapeHTML(p.description||p.name)}" style="--preset-color:${library==='factory'?p.color:'#b7c5a5'}"><span class="preset-icon">${library==='factory'?p.icon:'S'}</span><span><strong>${escapeHTML(p.name)}</strong><small>${library==='factory'?escapeHTML(p.subtitle):'YOUR PRESET'}</small></span></button>${library==='saved'?`<div class="preset-actions"><button class="preset-move" data-move="${escapeHTML(p.id)}" aria-label="Move ${escapeHTML(p.name)} to a folder" title="Move to folder">Move</button><button class="preset-delete" data-delete="${escapeHTML(p.id)}" aria-label="Delete ${escapeHTML(p.name)}" title="Delete preset">×</button></div>`:''}</div>`).join(''):'<p class="empty-presets">No matching tones in this folder. Try another search or go back to folders.</p>';
}
function clearPresetSearch(){presetQuery='';$('#preset-search').value='';}
function focusPreset(id){$$('[data-preset]').find(b=>b.dataset.preset===id)?.focus({preventScroll:true});}
function fillFolderOptions(){$('#saved-folder-options').replaceChildren(...[...new Set([DEFAULT_FOLDER,...getLibraryFolders('saved',saved).map(f=>f.name)])].map(name=>new Option(name,name)));}
function storePresets(next){localStorage.setItem('voltage.presets',JSON.stringify(next));saved=next;}
function renderTone(){$('#tone-title').textContent=activePreset.name;$('#tone-description').textContent=activePreset.description||'Your sound, just the way you like it.';$('#tone-badge').textContent=dirty?'MODIFIED TONE':PRESETS.some(p=>p.id===activePreset.id)?'FACTORY PRESET':'YOUR PRESET';}
function renderAmp(){
  $('#amp-bypass').innerHTML=powerIcon;
  const m=MODELS[settings.model];$('#amp-model-name').textContent=m.name;$('#amp-model-tag').textContent=m.tag;
  $$('[data-amp]').forEach(b=>{b.classList.toggle('active',b.dataset.amp===settings.model);b.setAttribute('aria-pressed',String(b.dataset.amp===settings.model));});
  $('#amp-bypass').classList.toggle('active',settings.ampEnabled);$('#amp-bypass').setAttribute('aria-pressed',String(settings.ampEnabled));$('#amp-bypass').setAttribute('aria-label',settings.ampEnabled?'Bypass amplifier':'Enable amplifier');
  $('#amp-controls').innerHTML=['gain','bass','middle','treble','presence','level'].map(k=>`<label class="knob-control"><span class="knob-label">${k.toUpperCase()}</span><span class="knob-wrap" style="--angle:${settings[k]*2.7}deg;--rotation:${settings[k]*2.7-135}deg"><span class="knob"></span><input class="knob-input" data-knob="${k}" type="range" min="0" max="100" value="${settings[k]}" aria-label="Amp ${k}" aria-valuetext="${(settings[k]/10).toFixed(1)} out of 10"/></span><output>${(settings[k]/10).toFixed(1)}</output></label>`).join('');
  const feel=[['tightness','Tightness','Keep low notes focused before distortion.',0,100,1],['sag','Sag','A little give under strong picking.',0,100,1],['power','Power drive','Add warmth and power-stage breakup.',0,100,1],['cabHighCut','Cab high cut','Soften the very top end of the cabinet.',3000,16000,100]];
  $('#amp-feel').innerHTML=feel.map(([key,label,hint,min,max,step])=>`<label title="${hint}"><span>${label}<output>${key==='cabHighCut'?(settings[key]/1000).toFixed(1)+' kHz':settings[key]+'%'}</output></span><input type="range" data-feel="${key}" aria-label="${label}" min="${min}" max="${max}" step="${step}" value="${settings[key]}"/><small>${hint}</small></label>`).join('');
  $('#cabinet').value=settings.cabinet;renderCabinetStatus();
}
function renderCabinetStatus(){$('#cabinet-status').textContent=engine.graph?.cabinetFallback?'FILTER FALLBACK':settings.cabinet==='off'?'CAB SIM OFF':settings.cabinet==='custom'?'CUSTOM IR':CABINETS[settings.cabinet]?.kind==='ir'?'MEASURED IR':'MODELED CAB';}
function renderEffects(){
  $('#pedals').innerHTML=EFFECTS.map((e,i)=>{const v=settings.effects[e.id],on=v.enabled&&!settings.fxBypassed;return `<article class="pedal ${on?'':'off'}" style="--pedal:${e.color};background:${e.bg};border-color:${e.color}44"><span class="pedal-number">${String(i+1).padStart(2,'0')}</span><h3>${e.name}</h3><p>${e.description}</p><div class="pedal-controls">${e.params.map(([k,label,min,max,step,unit])=>`<label class="pedal-control"><div><span>${label}</span><output>${format(v[k],unit)}</output></div><input type="range" data-effect="${e.id}" data-param="${k}" data-unit="${unit}" aria-label="${e.name} ${label}" min="${min}" max="${max}" step="${step}" value="${v[k]}" aria-valuetext="${format(v[k],unit)}"/></label>`).join('')}</div><button class="pedal-switch" data-switch="${e.id}" aria-label="${on?'Bypass':'Enable'} ${e.name}" aria-pressed="${on}">${on?'ON':'BYPASSED'}</button></article>`;}).join('');renderChain();
}
function renderChain(){const names={gate:'GATE',compressor:'COMP',octave:'OCTAVE',wah:'WAH',overdrive:'DRIVE',bitcrusher:'CRUSH',noise:'NOISE',chorus:'CHORUS',phaser:'PHASER',tremolo:'TREM',ringmod:'RING',delay:'DELAY',reverb:'REVERB'};$('#chain-labels').innerHTML=EFFECTS.map(e=>`${e.id==='bitcrusher'?'<span class="chain-item enabled chain-amp">AMP / CAB</span>':''}<span class="chain-item ${settings.effects[e.id].enabled&&!settings.fxBypassed?'enabled':''}">${names[e.id]}</span>`).join('');$('#bypass-effects').textContent=settings.fxBypassed?'Enable effects':'Bypass effects';$('#bypass-effects').setAttribute('aria-pressed',String(settings.fxBypassed));}
function applyPreset(p){settings=sanitizeSettings(p.settings);if(settings.cabinet==='custom'&&(!engine.customIR||settings.customIRId!==engine.customIRId)){settings.cabinet='open';notify('Reload the custom IR used by this preset. Open Back is active for now.');}activePreset=p;dirty=false;library=PRESETS.some(t=>t.id===p.id)?'factory':'saved';selectedFolder[library]=library==='factory'?p.folderId:normalizeFolderName(p.folder);engine.update(settings);renderPresets();renderTone();renderAmp();renderEffects();saveSession();}
function renderStatus(){
  renderCabinetStatus();
  const live=!!engine.stream,demo=!!engine.demo,running=engine.ctx?.state==='running';$('#status-dot').classList.toggle('live',running&&(live||demo));
  $('#connection-status').textContent=busy?'Connecting…':engine.ctx?.state==='suspended'?'Audio suspended':live?'Guitar connected':demo?'Demo playing':'Audio offline';
  $('#connect-button').innerHTML=busy?'Connecting…':powerIcon+(live?' Disconnect':' Connect guitar');
  $('#record-button').disabled=busy||recordStopping;$('#metronome-button').disabled=busy;$('#looper-button').disabled=busy;$('#settings-button').disabled=busy;
  $('#connect-button').disabled=busy;$('#input-device').disabled=busy;$('#input-channel').disabled=busy;$('#demo-button').textContent=demo?'Stop demo riff ■':'Try a demo riff ↗';$('#demo-button').disabled=busy;
  const a=engine.stream?.getAudioTracks()[0].getSettings();$('#input-channel').options[1].disabled=a?.channelCount===1;$('#input-channel').value=String(engine.channel);
  const sink=!!engine.ctx?.setSinkId;$('#output-device').disabled=!sink;$('#output-hint').textContent=sink?'Choose the interface your wired headphones are connected to.':'Output selection is unavailable here. Use your computer’s sound settings.';
  const latency=engine.ctx?((engine.ctx.baseLatency||0)+(engine.ctx.outputLatency||0))*1000:0;$('#latency-value').innerHTML=latency?`${latency.toFixed(1)} <small>ms</small>`:'— <small>ms</small>';$('#latency-value').title='Estimated browser output latency only. Input and hardware delay are additional.';
  const processing=a?['echoCancellation','noiseSuppression','autoGainControl'].filter(k=>a[k]===true):[];
  $('#audio-details').textContent=engine.ctx?`${engine.ctx.sampleRate.toLocaleString()} Hz · Estimated output latency: ${latency?latency.toFixed(1)+' ms':'unavailable'}. Input and hardware delay are additional.${a?.channelCount?' Input channels: '+a.channelCount+'.':''}${processing.length?' Your device reports audio processing still enabled: '+processing.join(', ')+'. Disable audio enhancements in system settings if available.':' Echo cancellation, noise suppression and auto gain are requested off.'}`:'Connect your guitar to see the sample rate and estimated output latency.';
  $('#engine-status').textContent=live?'LIVE INPUT · '+(a?.sampleRate||engine.ctx.sampleRate).toLocaleString()+' HZ':demo?'SYNTHESIZED DEMO · LIVE EFFECTS':'READY WHEN YOU ARE';
  $('#metronome-button').setAttribute('aria-pressed',String(!!engine.metroTimer));$('.metronome-tool').classList.toggle('metronome-active',!!engine.metroTimer);if(!engine.metroTimer)$('#metronome-status').textContent='Keep your own time';
}
function renderLooper(data=engine.loopState){const names={empty:'Record loop',recording:'Finish loop',playing:'Stop loop',overdubbing:'Finish overdub',stopped:'Play loop'};$('#looper-button').textContent=names[data.mode];$('#looper-button').classList.toggle('loop-recording',['recording','overdubbing'].includes(data.mode));$('#looper-overdub').disabled=!['playing','overdubbing'].includes(data.mode);$('#looper-overdub').textContent=data.mode==='overdubbing'?'Finish overdub':'Overdub';$('#looper-clear').disabled=data.mode==='empty';$('#looper-status').textContent=data.mode==='empty'?'60 seconds · Unlimited overdubs':`${data.mode.charAt(0).toUpperCase()+data.mode.slice(1)} · ${data.duration.toFixed(1)}s`;if(data.mode==='recording')loopStarted=performance.now();}
async function refreshDevices(){if(!navigator.mediaDevices?.enumerateDevices)return;try{const devices=await navigator.mediaDevices.enumerateDevices();const selected=engine.stream?.getAudioTracks()[0].getSettings().deviceId||$('#input-device').value;const fill=(selector,kind,value)=>{const el=$(selector);el.replaceChildren(new Option('System default',''));devices.filter(d=>d.kind===kind&&d.deviceId&&d.deviceId!=='default'&&d.deviceId!=='communications').forEach((d,i)=>el.add(new Option(d.label||`${kind==='audioinput'?'Input':'Output'} ${i+1}`,d.deviceId)));if([...el.options].some(o=>o.value===value))el.value=value;};fill('#input-device','audioinput',selected);fill('#output-device','audiooutput',engine.outputId);}catch{}}
async function connectInput(){if(busy)return;const device=$('#input-device').value,channel=Number($('#input-channel').value);busy=true;clearError();renderStatus();try{await engine.connect(settings,device,channel);}catch(e){showError(e.message);}finally{await refreshDevices();busy=false;renderStatus();}}
async function stopRecording(){if(recordStopping)return;recordStopping=true;$('#record-button').disabled=true;try{const result=await engine.stopRecording();if(result){if(recordURL)URL.revokeObjectURL(recordURL);recordURL=URL.createObjectURL(result.blob);$('#download-recording').href=recordURL;$('#download-recording').download=`Voltage-${new Date().toISOString().replace(/[:.]/g,'-')}.${result.extension}`;$('#download-recording').hidden=false;notify('Your take is ready. Download it to keep a copy.');}}finally{recordStopping=false;$('#record-button').disabled=false;$('#record-label').textContent='Record a take';$('.record-tool').classList.remove('recording');$('#record-format').disabled=false;}}
$('#preset-list').onclick=event=>{
  const folder=event.target.closest('[data-folder]');if(folder){selectedFolder[library]=folder.dataset.folder;renderPresets();$('#folder-heading').focus();return;}
  const b=event.target.closest('[data-preset]');if(b){const p=[...PRESETS,...saved].find(p=>p.id===b.dataset.preset);if(p){applyPreset(p);focusPreset(p.id);}return;}
  const move=event.target.closest('[data-move]');if(move){const p=saved.find(p=>p.id===move.dataset.move);if(!p)return;movingPresetId=p.id;fillFolderOptions();$('#move-preset-name').textContent=p.name;$('#move-folder').value=normalizeFolderName(p.folder);$('#move-dialog').showModal();$('#move-folder').focus();$('#move-folder').select();return;}
  const remove=event.target.closest('[data-delete]');if(remove){try{storePresets(saved.filter(p=>p.id!==remove.dataset.delete));if(activePreset.id===remove.dataset.delete){dirty=true;renderTone();saveSession();}renderPresets();$('#folder-heading').focus();notify('Preset removed from your library.');}catch{notify('Your browser could not update saved presets.');}}
};
$('#folder-back').onclick=()=>{const previous=selectedFolder[library];selectedFolder[library]=null;renderPresets();const button=$$('[data-folder]').find(b=>b.dataset.folder===previous);(button||$('#folder-heading')).focus();};
$('#preset-search').oninput=()=>{presetQuery=$('#preset-search').value;renderPresets();};
$$('[data-library]').forEach(b=>b.onclick=()=>{library=b.dataset.library;clearPresetSearch();renderPresets();});
$('#save-preset').onclick=()=>{$('#preset-name').setCustomValidity('');$('#preset-name').value=(activePreset.name+(dirty?' Custom':'')).slice(0,40);fillFolderOptions();$('#preset-folder').value=library==='saved'&&selectedFolder.saved?selectedFolder.saved:activePreset.folder||DEFAULT_FOLDER;$('#save-dialog').showModal();$('#preset-name').focus();$('#preset-name').select();};$('#close-save').onclick=()=>$('#save-dialog').close();
$('#save-form').onsubmit=event=>{
  event.preventDefault();const name=$('#preset-name').value.trim();if(!name){$('#preset-name').setCustomValidity('Enter a preset name.');$('#preset-name').reportValidity();return;}if(saved.length>=100){notify('Your library holds 100 presets. Remove a preset to save another.');return;}
  const p={id:crypto.randomUUID(),name:name.slice(0,40),folder:resolveSavedFolder($('#preset-folder').value,saved),description:'Your sound, just the way you like it.',settings:clone(settings)};
  try{storePresets([...saved,p]);}catch{notify('Your browser could not save this preset. Check available storage or private browsing settings.');return;}
  library='saved';selectedFolder.saved=p.folder;clearPresetSearch();activePreset=p;dirty=false;renderPresets();renderTone();saveSession();$('#save-dialog').close();focusPreset(p.id);notify(settings.cabinet==='custom'?'Tone saved. Reload the custom IR after reopening Voltage.':`Tone saved in ${p.folder} on this device.`);
};$('#preset-name').oninput=()=>$('#preset-name').setCustomValidity('');
$('#close-move').onclick=()=>$('#move-dialog').close();
$('#move-form').onsubmit=event=>{
  event.preventDefault();if(!saved.some(p=>p.id===movingPresetId)){notify('This preset is no longer in your library.');$('#move-dialog').close();return;}
  try{storePresets(moveSavedPreset(saved,movingPresetId,$('#move-folder').value));}catch{notify('Your browser could not move this preset. Check available storage.');return;}
  const p=saved.find(p=>p.id===movingPresetId);if(activePreset.id===p.id)activePreset=p;
  library='saved';selectedFolder.saved=p.folder;clearPresetSearch();renderPresets();$('#move-dialog').close();focusPreset(p.id);notify(`Preset moved to ${p.folder}.`);
};
$$('[data-amp]').forEach(b=>b.onclick=()=>{settings.model=b.dataset.amp;changed();renderAmp();});$('#amp-bypass').onclick=()=>{settings.ampEnabled=!settings.ampEnabled;changed();renderAmp();};
$('#amp-controls').oninput=event=>{const el=event.target;if(!el.dataset.knob)return;const value=Number(el.value);settings[el.dataset.knob]=value;const wrap=el.closest('.knob-wrap');wrap.style.setProperty('--angle',value*2.7+'deg');wrap.style.setProperty('--rotation',value*2.7-135+'deg');wrap.parentElement.querySelector('output').textContent=(value/10).toFixed(1);el.setAttribute('aria-valuetext',(value/10).toFixed(1)+' out of 10');changed();};
$('#amp-feel').oninput=event=>{const el=event.target,key=el.dataset.feel;if(!key)return;settings[key]=Number(el.value);el.closest('label').querySelector('output').textContent=key==='cabHighCut'?(settings[key]/1000).toFixed(1)+' kHz':settings[key]+'%';changed();};
