$('#ir-file').onchange=async()=>{const file=$('#ir-file').files[0];if(!file)return;try{await engine.loadIR(file);let option=$('#cabinet').querySelector('[value=custom]');if(!option){option=new Option('Custom IR','custom');$('#cabinet').add(option);}option.textContent=file.name;settings.cabinet='custom';settings.customIRId=engine.customIRId;changed();renderAmp();notify(`Loaded ${file.name}. Custom IRs stay in this session.`);}catch(e){showError(e.message);}finally{$('#ir-file').value='';}};
$('#pedals').oninput=event=>{const el=event.target;if(!el.dataset.effect)return;const value=Number(el.value);settings.effects[el.dataset.effect][el.dataset.param]=value;el.closest('label').querySelector('output').textContent=format(value,el.dataset.unit);el.setAttribute('aria-valuetext',format(value,el.dataset.unit));changed();};
$('#pedals').onclick=event=>{const b=event.target.closest('[data-switch]');if(!b)return;const id=b.dataset.switch;if(settings.fxBypassed){settings.fxBypassed=false;settings.effects[id].enabled=true;}else settings.effects[id].enabled=!settings.effects[id].enabled;changed();renderEffects();};$('#bypass-effects').onclick=()=>{settings.fxBypassed=!settings.fxBypassed;changed();renderEffects();};
$('#connect-button').onclick=async()=>{if(busy)return;try{if(engine.stream){busy=true;renderStatus();if(engine.recorder?.state==='recording')await stopRecording();await engine.disconnect();clearError();busy=false;renderStatus();}else await connectInput();}catch(e){busy=false;renderStatus();showError(e.message);}};
$('#input-device').onchange=()=>{if(engine.stream)connectInput();};$('#input-channel').onchange=()=>engine.setChannel(Number($('#input-channel').value));
$('#output-device').onchange=async()=>{try{await engine.setOutput($('#output-device').value);clearError();}catch(e){$('#output-device').value=engine.outputId;showError(e.message);}};
$('#input-trim').oninput=()=>{const v=Number($('#input-trim').value);engine.setTrim(v);$('#input-trim-value').textContent=(v>0?'+':'')+v+' dB';};
$('#master-volume').oninput=()=>{engine.setVolume(Number($('#master-volume').value));$('#master-value').textContent=engine.volume+'%';};
$('#mute-button').onclick=()=>{engine.setMuted(!engine.muted);$('#mute-button').setAttribute('aria-pressed',String(engine.muted));$('#mute-button').setAttribute('aria-label',engine.muted?'Unmute output':'Mute output');$('#mute-button').textContent=engine.muted?'◖×':'◖))';};
$('#demo-button').onclick=async()=>{if(busy)return;clearError();try{if(engine.demo){if(engine.recorder?.state==='recording')await stopRecording();engine.stopDemo();engine.looperAction('clear');}else await engine.startDemo(settings);}catch(e){showError(e.message);}renderStatus();};
$('#help-button').onclick=()=>$('#help-dialog').showModal();$('#help-done').onclick=()=>$('#help-dialog').close();$('#settings-button').onclick=()=>{renderStatus();$('#settings-dialog').showModal();refreshDevices();};
$('#tuner-button').onclick=()=>{if(!engine.stream&&!engine.demo){notify('Connect your guitar before opening the tuner.');return;}$('#tuner-dialog').showModal();engine.setTuning($('#tuner-mute').checked);};$('#tuner-mute').onchange=()=>engine.setTuning($('#tuner-mute').checked);$('#tuner-dialog').addEventListener('close',()=>engine.setTuning(false));
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close();}}));
$('#metronome-button').onclick=async()=>{try{if(engine.metroTimer)engine.stopMetronome();else{await engine.initialize(settings);engine.startMetronome(clamp(Number($('#bpm').value)||100,30,240));}}catch(e){showError(e.message);}};
$('#bpm').onchange=()=>{const v=clamp(Math.round(Number($('#bpm').value)||100),30,240);$('#bpm').value=v;engine.bpm=v;};let taps=[];$('#tap-tempo').onclick=()=>{const now=performance.now();if(taps.length&&now-taps.at(-1)>2000)taps=[];taps.push(now);if(taps.length>5)taps.shift();if(taps.length>=2){const v=clamp(Math.round(60000/((now-taps[0])/(taps.length-1))),30,240);$('#bpm').value=v;engine.bpm=v;}};
$('#record-button').onclick=async()=>{try{if(engine.recorder?.state==='recording')await stopRecording();else{engine.startRecording($('#record-format').value);$('#record-label').textContent='Stop recording';$('.record-tool').classList.add('recording');$('#download-recording').hidden=true;$('#record-format').disabled=true;}}catch(e){showError(e.message);}};
$('#looper-button').onclick=()=>{try{const mode=engine.loopState.mode;if(['recording','overdubbing'].includes(mode))engine.looperAction('finish');else if(mode==='playing')engine.looperAction('stop');else if(mode==='stopped')engine.looperAction('play');else if(engine.stream||engine.demo)engine.looperAction('record');else notify('Connect your guitar or start the demo before recording a loop.');}catch(e){showError(e.message);}};
$('#looper-overdub').onclick=()=>engine.looperAction(engine.loopState.mode==='overdubbing'?'finish':'overdub');$('#looper-clear').onclick=()=>engine.looperAction('clear');
document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||e.target.matches('input,select,textarea')||$('dialog[open]'))return;if(e.key.toLowerCase()==='m')$('#mute-button').click();if(e.key.toLowerCase()==='t')$('#tuner-button').click();});navigator.mediaDevices?.addEventListener('devicechange',refreshDevices);
window.addEventListener('pagehide',()=>{engine.stopInput();engine.stopDemo();engine.stopMetronome();engine.ctx?.suspend();});window.addEventListener('beforeunload',e=>{if(engine.recorder?.state==='recording'||engine.loopState.mode!=='empty'){e.preventDefault();e.returnValue='';}});
const inputData=new Float32Array(4096),rawInputData=new Float32Array(1024),outputData=new Float32Array(1024),clipData=new Float32Array(1024);let lastMeter=0,lastPitch=0,clipUntil=0,smoothedCents=0,lastMidi=null;
function animate(now){
  requestAnimationFrame(animate);if(now-lastMeter<45)return;lastMeter=now;
  if(engine.graph){
    engine.graph.inputAnalyser.getFloatTimeDomainData(inputData);engine.graph.rawInputAnalyser.getFloatTimeDomainData(rawInputData);engine.graph.outputAnalyser.getFloatTimeDomainData(outputData);engine.graph.preLimiterAnalyser.getFloatTimeDomainData(clipData);
    let ip=0,op=0,cp=0;for(const v of rawInputData)ip=Math.max(ip,Math.abs(v));for(const v of outputData)op=Math.max(op,Math.abs(v));for(const v of clipData)cp=Math.max(cp,Math.abs(v));
    const db=ip>0.00001?20*Math.log10(ip):-100,level=clamp((20*Math.log10(op||0.00001)+60)/60*100,0,100);$('#input-db').textContent=db>-80?`${db.toFixed(1)} dB`:'−∞ dB';$('#input-meter').style.width=clamp((db+60)/60*100,0,100)+'%';$('#input-meter').style.background=ip>0.97?'#f3896f':'#b0c896';$('#output-meter').style.height=level+'%';$('.output-meter').style.setProperty('--horizontal-level',level+'%');
    if(cp>0.97||ip>0.97)clipUntil=now+1000;$('#clip-indicator').textContent=now<clipUntil?'HOT':'CLEAN';$('#clip-indicator').classList.toggle('clipping',now<clipUntil);$('#clip-indicator').title='HOT means input clipping or a high signal before the output limiter. Lower input gain, amp level, or master.';
    if($('#tuner-dialog').open&&now-lastPitch>130){lastPitch=now;const p=detectPitch(inputData,engine.ctx.sampleRate);if(p){smoothedCents=lastMidi===p.midi?smoothedCents*0.55+p.cents*0.45:p.cents;lastMidi=p.midi;const name=['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'][p.midi%12]+(Math.floor(p.midi/12)-1);$('#tuner-note').textContent=name;$('#tuner-note').classList.toggle('in-tune',Math.abs(smoothedCents)<5);$('#tuner-frequency').textContent=p.frequency.toFixed(1)+' Hz';$('#tuner-cents').textContent=Math.abs(smoothedCents)<5?'In tune':`${smoothedCents>0?'+':''}${smoothedCents.toFixed(0)} cents · ${smoothedCents>0?'Tune down':'Tune up'}`;$('#tuner-needle').style.left=clamp(50+smoothedCents,0,100)+'%';$('#tuner-summary').textContent=name+' · '+p.frequency.toFixed(1)+' Hz';}else{$('#tuner-note').textContent='—';$('#tuner-note').classList.remove('in-tune');$('#tuner-frequency').textContent='Play one open string';$('#tuner-cents').textContent='Waiting for a clear note';$('#tuner-needle').style.left='50%';lastMidi=null;}}
  }else{$('#input-meter').style.width='0%';$('#output-meter').style.height='0%';$('.output-meter').style.setProperty('--horizontal-level','0%');$('#input-db').textContent='−∞ dB';}
  if(engine.recorder?.state==='recording'){const s=Math.floor((now-engine.recordStarted)/1000);$('#record-time').textContent=`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;if(s>=1800&&!recordStopping)stopRecording().catch(e=>showError(e.message));}
  if(engine.loopState.mode==='recording')$('#looper-status').textContent=`Recording · ${Math.min(60,(now-loopStarted)/1000).toFixed(1)} / 60s`;
}
